/* Independent reference-based office design; never converts an uploaded workbook silently. */
(function(){'use strict';
const el=id=>document.getElementById(id);let bundle=null,options={scheme_indices:[0,4]},controller=null;
const load=document.createElement('button');load.type='button';load.className='btn';load.textContent='载入办公楼完整荷载课程案例';el('modelFile').closest('.field').after(load);
const panel=document.createElement('section');panel.hidden=true;panel.innerHTML='<h3>办公楼恒活风震案例</h3><p>参考平面基础上的新课程设计；节点、楼板、柱脚与基础性能另行交接。</p><div id="officeInputs"></div><button class="btn" id="applyOfficeInputs">应用案例参数</button><button class="btn" id="cancelOfficeRun" disabled>停止办公楼分析</button><p id="officeScopeStatus"></p>';el('iterationParams').before(panel);
const fields=[['floor_dead_kPa','楼面恒载 kPa'],['roof_dead_kPa','屋面恒载 kPa'],['office_live_kPa','办公活载 kPa'],['roof_live_kPa','屋面活载 kPa'],['wind_basic_kPa','基本风压 kPa'],['Tg_s','采用特征周期 s']];
const client=SteelMindOffice.createOfficeClient({getBundle:()=>bundle,getOptions:()=>options,gateway:()=>el('toolBase').value.trim(),onEvent:event=>{if(event.type==='office_progress'){el('iterationStatus').textContent='办公楼方案 '+event.scheme+' · '+event.stage+(event.current?' '+event.current+'/'+event.total:'');el('iterationTrace').textContent=el('iterationStatus').textContent}else if(event.type==='workflow_started')el('iterationStatus').textContent='办公楼完整分析已启动'}});
function reset(){if(controller)controller.abort();bundle=null;client.invalidate();panel.hidden=true;window.lastOfficeReport=null;el('cancelOfficeRun').disabled=true}
load.onclick=async()=>{if(controller||activeController){el('fileStatus').textContent='请先停止当前对话或分析，再切换办公楼案例';return}load.disabled=true;try{const r=await fetch(el('toolBase').value.trim().replace(/\/$/,'')+'/workflow/office-design/reference');if(!r.ok)throw Error('读取课程案例 HTTP '+r.status);bundle=(await r.json()).bundle;client.invalidate();window.explicitWorkbookTables=null;window.explicitAnalysisReady=false;window.excelChatSession?.invalidate();window.lastIterationReport=null;window.lastOfficeReport=null;el('runEngineeringOutputs').disabled=true;panel.hidden=false;el('officeInputs').replaceChildren();for(const [key,label] of fields){const row=document.createElement('div');row.className='field';const text=document.createElement('label');text.textContent=label;const input=document.createElement('input');input.type='number';input.step='any';input.id='office-'+key;input.value=bundle.parameters[key];row.append(text,input);el('officeInputs').append(row)}el('officeScopeStatus').textContent='308节点 / 540计算段；采用已确认课程假定，先计算参考截面，再检查保守改型方案。';el('fileStatus').textContent='已载入办公楼完整荷载课程案例；旧Excel自重案例仍可重新上传。';document.querySelector('[data-page="page-tools"]').click();el('flow-tab-2').click();el('iterationStatus').textContent='办公楼课程案例就绪，可运行工作流2';add('assistant','已载入办公楼恒活风震课程案例。它采用参考平面重建的新布置；不会当作原Excel模型。可运行工作流2，或在对话中要求分析该办公楼案例。')}catch(e){el('fileStatus').textContent=e.message}finally{load.disabled=false}};
el('applyOfficeInputs').onclick=()=>{try{if(controller)throw Error('请先停止当前分析');for(const [key] of fields){const value=Number(el('office-'+key).value);if(!Number.isFinite(value)||value<0||(key==='Tg_s'&&value<=0))throw Error('请填写有效的荷载及周期数值');bundle.parameters[key]=value}client.invalidate();window.lastOfficeReport=null;el('runEngineeringOutputs').disabled=true;el('iterationStatus').textContent='参数已应用，请重新分析'}catch(e){el('iterationStatus').textContent=e.message}};
async function analyze({signal}={}){if(!bundle)throw Error('请先载入办公楼课程案例');if(controller)throw Error('办公楼分析正在运行，请等待或停止当前任务');const external=signal;const local=new AbortController();const relay=()=>local.abort();if(external?.aborted)local.abort();else external?.addEventListener('abort',relay,{once:true});controller=local;signal=local.signal;el('cancelOfficeRun').disabled=false;el('runSectionIteration').disabled=true;try{const result=await client.analyze({signal});window.lastOfficeReport=result;el('iterationResult').textContent=JSON.stringify(result,null,2);el('iterationStatus').textContent='办公楼分析完成 · 上部杆系 '+result.design_status+' · 建筑构造交接待验证';el('runEngineeringOutputs').disabled=false;el('officeScopeStatus').textContent='验算统计 '+JSON.stringify(result.code_check_summary)+'；二阶对照 '+result.verification_status;return result}finally{external?.removeEventListener('abort',relay);if(controller===local)controller=null;el('cancelOfficeRun').disabled=true;el('runSectionIteration').disabled=false}}
async function generate({signal}={}){await analyze({signal});el('outputsStatus').textContent='正在生成办公楼计算书和图纸…';const pkg=await client.generate({signal});const final={ok:true,status:pkg.file_generation_status,artifacts:{engineering_package:pkg}};await consumeEngineeringOutputs(new Response('data: '+JSON.stringify({type:'workflow_completed',result:final})+'\n\n'));document.querySelector('[data-page="page-results"]').click();el('result-tab-0').click();return {ok:true,status:pkg.file_generation_status,draft:pkg.draft,upstream_check_summary:pkg.upstream_check_summary,artifacts:pkg.artifacts}}
const oldRun=el('runSectionIteration').onclick;el('runSectionIteration').onclick=async()=>{if(!bundle)return oldRun();try{await analyze();if(el('autoGenerateOutputs').checked)await generate()}catch(e){el('iterationStatus').textContent=e.name==='AbortError'?'办公楼分析已停止':'办公楼分析未完成：'+e.message}};
const oldOutputs=el('runEngineeringOutputs').onclick;el('runEngineeringOutputs').onclick=async()=>{if(!bundle)return oldOutputs();const button=el('runEngineeringOutputs');button.disabled=true;try{return await generate()}catch(e){el('outputsStatus').textContent=e.message}finally{button.disabled=false}};
const oldChat=el('chatGenerateArtifacts').onclick;el('chatGenerateArtifacts').onclick=async()=>{if(!bundle)return oldChat();try{await generate()}catch(e){add('assistant',e.message)}};
el('cancelOfficeRun').onclick=()=>controller?.abort();el('modelFile').addEventListener('change',reset,true);el('newConversation').addEventListener('click',reset,true);el('conversationList').addEventListener('click',event=>{if(event.target.closest('[data-conversation-id]'))reset()},true);
const caseField=document.createElement('div');caseField.className='field';const label=document.createElement('label');label.textContent='办公楼实际静力工况';const select=document.createElement('select');for(const value of ['G','Q_OFFICE','Q_STAIR','Q_ROOF','W_XP','W_XN','W_YP','W_YN']){const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option)}caseField.append(label,select);el('viewerParams').before(caseField);caseField.hidden=true;
const oldView=el('runModelView').onclick;el('runModelView').onclick=async()=>{if(!bundle){caseField.hidden=true;return oldView()}caseField.hidden=false;try{let result;if(client.state().result)result=await client.viewer(select.value);else{const tables=structuredClone(bundle.tables);delete tables.Office_Design;const response=await fetch(el('toolBase').value.trim().replace(/\/$/,'')+'/workflow/explicit-model/visualize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({payload:{tables}})});result=await response.json();if(!response.ok)throw Error(result.detail||'预览失败')}await showOpenSeesModel(result,{reveal:false})}catch(e){el('viewerStatus').textContent=e.message}};
window.officeWorkflow={state:client.state,analyze,generate,results:client.results};
})();
